cd /home/admin/backend && php artisan tinker --execute="
use Illuminate\Support\Facades\DB;
\$c = DB::table('Campus')->where('id', 17)->first();

// Simulate resolveCampusBaseUrl with no request
\$campusUrl = !empty(\$c->URL) ? rtrim((string)\$c->URL, '/') : '';
\$appUrl = rtrim((string)config('app.url'), '/');
echo 'Campus URL: [' . \$campusUrl . ']' . PHP_EOL;
echo 'App URL: [' . \$appUrl . ']' . PHP_EOL;

// If no request context: falls back to appUrl or campusUrl
echo 'Webhook URL (no request context): ' . (\$appUrl ?: \$campusUrl ?: 'http://localhost') . '/api/v1/line/webhook/17' . PHP_EOL;
" 2>&1

