cd /home/admin/backend && php artisan tinker --execute="
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Http;
\$c = DB::table('Campus')->where('id', 17)->first();
\$token = \$c->messaging_channel_token ?? '';
echo 'Token length: ' . strlen(\$token) . PHP_EOL;
echo 'Token prefix: ' . substr(\$token, 0, 20) . '...' . PHP_EOL;
// 測試 Channel Access Token 是否有效
try {
    \$res = Http::withToken(\$token)->get('https://api.line.me/v2/bot/info');
    echo 'LINE Bot Info Status: ' . \$res->status() . PHP_EOL;
    echo 'Body: ' . \$res->body() . PHP_EOL;
} catch (\Exception \$e) {
    echo 'Error: ' . \$e->getMessage() . PHP_EOL;
}
" 2>&1

